function getTrendMicroVisionOneTranslation(key, lang) {
    return (trendmicrovisiononeTranslations[lang] && trendmicrovisiononeTranslations[lang][key]) ||
           (trendmicrovisiononeTranslations.en && trendmicrovisiononeTranslations.en[key]) || null;
}

function applyTrendMicroVisionOneTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.trend-micro-vision-one.") || key.startsWith("review.common."))) {
            const translation = getTrendMicroVisionOneTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} trend-micro-vision-one translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyTrendMicroVisionOneTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyTrendMicroVisionOneTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyTrendMicroVisionOneTranslations(window.i18n?.getCurrentLanguage() || "en");
}
